// Generated by esquadro: do not edit. Keyboard shortcuts: a hook for a
// page's keys (ignored while typing in a field), and the list of them all,
// opened with "?".
import { useEffect, useState } from "react"
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { t } from "./i18n.ts"
import { paletteKey } from "./palette.tsx"

/** Whether a key press is someone typing (in a field, a menu, a dialog). */
export function typing(e: KeyboardEvent): boolean {
  const el = e.target as HTMLElement | null
  return (
    e.metaKey ||
    e.ctrlKey ||
    e.altKey ||
    !!el?.closest("input, textarea, select, [contenteditable=true], [role=dialog], [role=menu], [role=listbox]")
  )
}

/** Calls the handler of each key pressed, unless someone is typing. */
/** Whether a dialog, a menu or a popover is open over the page. */
function layerOpen(): boolean {
  return document.querySelector('[role="dialog"][data-state="open"], [role="alertdialog"][data-state="open"], [role="menu"][data-state="open"], [role="listbox"][data-state="open"]') !== null
}

export function useKeys(keys: Record<string, (e: KeyboardEvent) => void>, enabled = true) {
  useEffect(() => {
    if (!enabled) return
    const onKey = (e: KeyboardEvent) => {
      // A dialog or a menu open takes its keys (Esc closes it, not the page).
      if (typing(e) || e.defaultPrevented || layerOpen()) return
      const run = keys[e.key]
      if (run) {
        e.preventDefault()
        run(e)
      }
    }
    document.addEventListener("keydown", onKey)
    return () => document.removeEventListener("keydown", onKey)
  })
}

/** The shortcuts, opened with "?". Once, in src/pages/__root.tsx. */
export function ShortcutsHelp() {
  const [open, setOpen] = useState(false)
  useKeys({ "?": () => setOpen(true) })
  const groups: [string, [string, string][]][] = [
    [
      t("shortcutsEverywhere"),
      [
        [paletteKey, t("commandPalette")],
        ["/", t("search")],
        ["?", t("shortcuts")],
      ],
    ],
    [
      t("shortcutsList"),
      [
        ["j  ↓", t("keyNext")],
        ["k  ↑", t("keyPrevious")],
        ["Enter  o", t("view")],
        ["e", t("edit")],
        ["x", t("selectRow")],
      ],
    ],
    [
      t("shortcutsRecord"),
      [
        ["e", t("edit")],
        ["Esc  u", t("goBack")],
        ["1  s…", t("keyAction")],
      ],
    ],
    [
      t("shortcutsQueue"),
      [
        ["j  ↓", t("keyNext")],
        ["k  ↑", t("keyPrevious")],
        ["Enter", t("view")],
        ["1  s…", t("keyAction")],
      ],
    ],
  ]
  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>{t("shortcuts")}</DialogTitle>
          <DialogDescription>{t("shortcutsHint")}</DialogDescription>
        </DialogHeader>
        <div className="flex flex-col gap-4">
          {groups.map(([title, keys]) => (
            <div key={title} className="flex flex-col gap-1.5">
              <div className="text-xs font-medium text-muted-foreground">{title}</div>
              {keys.map(([k, what]) => (
                <div key={k + what} className="flex items-center justify-between text-sm">
                  <span>{what}</span>
                  <span className="flex gap-1">
                    {k.split("  ").map((part) => (
                      <kbd key={part} className="rounded border bg-muted px-1.5 py-0.5 font-mono text-xs">
                        {part}
                      </kbd>
                    ))}
                  </span>
                </div>
              ))}
            </div>
          ))}
        </div>
      </DialogContent>
    </Dialog>
  )
}
